  [25026] = { "毎秒マナ $N1。\n$N2ヤード以内の最も近い敵のtonkに$N3秒ごとに自動で射撃し、一発ごとに$N4のダメージを与えます。", nil, 0x3b2016d2, nil, "um" },
  [25027] = { "毎秒マナ 10。\n前方$N4ヤード以内のすべてのtonkに$N3秒ごとに$N2のダメージを与えます。さらに移動速度を$N5%まで低下させ、$D2の間、毎秒$N6のダメージを与えます。", nil, 0xec27c501, nil, "um" },
  [25028] = { "敵にFireダメージを与えます。", nil, 0x6c371710, nil, "um" },
