  [25817] = { "$D1の間、$N2秒ごとに周囲のグループメンバー全員の体力を$N1回復します。ドルイドは呪文を維持するために精神を集中し続ける必要があります。", "$N2秒ごとに近くのパーティーメンバーの体力を$N1回復します。", 0xd1533eff, 0x7cc0de27, "uu" },
